89	// The first load of a fresh tab has not spoken to GitHub yet, so no header has said
90	// what the limit is — and that is precisely the load where "you are anonymous, and
91	// your github.com session is not a credential" needs saying.
92	test('no credential at all reads as anonymous before any header has said so', () => {
93	  assert.ok(credentialAdvice('unknown', { hasToken: false }));
94	  assert.equal(credentialAdvice('unknown', { hasToken: true }), null);
